INSERT INTO public.translations (locale, key, value) VALUES
  ('en', 'onboardingBeatWelcome1', 'Welcome to MatchMe… You do not swipe or browse profiles. MatchMe looks for people nearby who share your interests and intentions, then lets you decide what to do next.'),
  ('en', 'onboardingBeatWelcome2', 'Finish your profile, choose what you are here for, and set your matching controls. MatchMe can keep working in the background while you live your life.'),
  ('en', 'onboardingBeatHome1', 'This is your home screen. It shows whether you are visible and lets you manage matching without making you hunt through menus. The switch controls visibility; it does not close your account.'),
  ('en', 'onboardingBeatHome2', 'The cards up top show nearby people and online activity. Tap a card to open it.'),
  ('en', 'onboardingBeatHome3', 'Below, your most recent matches and chats are waiting, so you can pick up right where you left off.'),
  ('en', 'onboardingBeatHome4', 'These chips narrow what you see here… choose the kinds of connections you want.'),
  ('en', 'onboardingBeatNearby1', 'This map shows an approximate count of visible people inside your matching radius. Nobody sees your exact location.'),
  ('en', 'onboardingBeatFinish1', 'That is the idea… MatchMe works quietly in the background. When someone matches, you can view their profile, message briefly, or meet in person. You can close the app and come back when you are ready.'),
  ('es', 'onboardingBeatWelcome1', 'Bienvenido a MatchMe… No deslizas ni recorres perfiles. MatchMe busca personas cercanas que comparten tus intereses e intenciones y tú decides qué hacer después.'),
  ('es', 'onboardingBeatWelcome2', 'Completa tu perfil, elige para qué estás aquí y ajusta tus controles. MatchMe puede seguir funcionando en segundo plano mientras vives tu vida.'),
  ('es', 'onboardingBeatHome1', 'Esta es tu pantalla de inicio. Muestra si estás visible y te permite gestionar las coincidencias sin buscar en varios menús. El interruptor controla la visibilidad; no cierra tu cuenta.'),
  ('es', 'onboardingBeatHome2', 'Las tarjetas superiores muestran personas cercanas y actividad en línea. Toca una tarjeta para abrirla.'),
  ('es', 'onboardingBeatHome3', 'Abajo te esperan tus coincidencias y conversaciones recientes para que continúes donde lo dejaste.'),
  ('es', 'onboardingBeatHome4', 'Estas etiquetas limitan lo que ves aquí… elige el tipo de conexiones que deseas.'),
  ('es', 'onboardingBeatNearby1', 'Este mapa muestra una cantidad aproximada de personas visibles dentro de tu radio de coincidencia. Nadie ve tu ubicación exacta.'),
  ('es', 'onboardingBeatFinish1', 'Esta es la idea… MatchMe funciona en silencio en segundo plano. Cuando alguien coincide contigo, puedes ver su perfil, escribir un mensaje breve o conocerlo en persona. Puedes cerrar la aplicación y volver cuando quieras.'),
  ('he', 'onboardingBeatWelcome1', 'ברוך הבא ל-MatchMe… אין צורך להחליק או לדפדף בפרופילים. MatchMe מחפש אנשים קרובים שחולקים איתך על התענוקים והכוונות, ואתם מחליטים מה לעשות אחר כך.'),
  ('he', 'onboardingBeatWelcome2', 'השלימו את הפרופיל, בחרו למה אתם כאן והגדירו את בקרת ההתאמה. MatchMe יכול להמשיך לעבוד ברקע בזמן שאתם חיים את החיים.'),
  ('he', 'onboardingBeatHome1', 'זהו מסך הבית שלכם. הוא מראה אם אתם גלויים ומאפשר לנהל את ההתאמה בלי לחפש בתוך תפריטים. המתג שולט בנראות; הוא לא סוגר את החשבון.'),
  ('he', 'onboardingBeatHome2', 'הכרטיסים למעלה מציגים אנשים קרובים ופעילות מקוונת. הקישו על כרטיס כדי לפתוח אותו.'),
  ('he', 'onboardingBeatHome3', 'למטה מחכים לכם התאמות ושיחות אחרונות, כדי שתוכלו להמשיך מהמקום שבו עצרתם.'),
  ('he', 'onboardingBeatHome4', 'התוויות מסננות מה אתם רואים כאן… בחרו את סוגי הקשרים שאתם רוצים.'),
  ('he', 'onboardingBeatNearby1', 'המפה מציגה כמות משוערת של אנשים גלויים בתוך רדיוס ההתאמה שלכם. איש אינו רואה את המיקום המדויק שלכם.'),
  ('he', 'onboardingBeatFinish1', 'זה הרעיון… MatchMe עובד בשקט ברקע. כשמתקבלת התאמה, אפשר לראות את הפרופיל, לשלוח הודעה קצרה או להיפגש באופן אישי. אפשר לסגור את האפליקציה ולחזור כשאתם מוכנים.')
